--
-- Name: comm_messages; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.comm_messages (
    message_id uuid DEFAULT gen_random_uuid() NOT NULL,
    entity_type text NOT NULL,
    entity_id uuid NOT NULL,
    gmail_message_id text NOT NULL,
    thread_id text,
    direction text,
    subject text,
    snippet text,
    from_email text,
    to_emails text[] DEFAULT '{}'::text[] NOT NULL,
    occurred_at timestamp with time zone NOT NULL,
    seen_by uuid,
    sent_by_platform boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    kind text DEFAULT 'email'::text NOT NULL,
    starts_at timestamp with time zone,
    ends_at timestamp with time zone,
    attendees text[] DEFAULT '{}'::text[] NOT NULL,
    event_link text,
    rfc_message_id text,
    attachment_names text[] DEFAULT '{}'::text[] NOT NULL,
    mailbox_user_id uuid,
    notes text,
    CONSTRAINT comm_messages_direction_check CHECK (((direction IS NULL) OR (direction = ANY (ARRAY['inbound'::text, 'outbound'::text])))),
    CONSTRAINT comm_messages_email_needs_direction CHECK (((kind <> 'email'::text) OR (direction IS NOT NULL))),
    CONSTRAINT comm_messages_entity_type_check CHECK ((entity_type = ANY (ARRAY['investor'::text, 'deal'::text, 'funding'::text]))),
    CONSTRAINT comm_messages_kind_check CHECK ((kind = ANY (ARRAY['email'::text, 'meeting'::text, 'touch'::text])))
);


--
-- Name: COLUMN comm_messages.mailbox_user_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.comm_messages.mailbox_user_id IS 'The connected Google mailbox this row was read from or sent by. gmail_message_id and thread_id are only resolvable within it.';


