--
-- Name: crm_plan_items; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.crm_plan_items (
    plan_item_id uuid DEFAULT gen_random_uuid() NOT NULL,
    deal_id uuid NOT NULL,
    item_type text NOT NULL,
    owner_id uuid,
    due_date date,
    status text DEFAULT 'open'::text NOT NULL,
    body text,
    sort_order integer DEFAULT 0 NOT NULL,
    nda_signed_date date,
    fs_target_date date,
    fs_date_completed date,
    fs_date_sent_to_client date,
    fs_analysis_link text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    resolved_on date,
    email_subject text,
    title text,
    custom_fields jsonb DEFAULT '[]'::jsonb NOT NULL,
    email_enabled boolean DEFAULT false NOT NULL,
    description text,
    CONSTRAINT crm_plan_items_fs_only_chk CHECK ((((fs_target_date IS NULL) AND (fs_date_completed IS NULL) AND (fs_date_sent_to_client IS NULL) AND (fs_analysis_link IS NULL)) OR (item_type = 'feasibility_study'::text))),
    CONSTRAINT crm_plan_items_nda_only_chk CHECK (((nda_signed_date IS NULL) OR (item_type = 'nda'::text))),
    CONSTRAINT crm_plan_items_status_chk CHECK ((((item_type = ANY (ARRAY['next_step'::text, 'nda'::text, 'email'::text, 'task'::text, 'first_touch'::text])) AND (status = ANY (ARRAY['open'::text, 'done'::text, 'cancelled'::text]))) OR ((item_type = 'feasibility_study'::text) AND (status = ANY (ARRAY['Not run'::text, 'Requested'::text, 'In progress'::text, 'Halted — no composition data'::text, 'GO'::text, 'HOLD'::text, 'REDIRECT'::text]))))),
    CONSTRAINT crm_plan_items_type_chk CHECK ((item_type = ANY (ARRAY['next_step'::text, 'nda'::text, 'feasibility_study'::text, 'email'::text, 'task'::text, 'first_touch'::text])))
);


