    source text DEFAULT 'manual'::text NOT NULL,
    priority text,
    source_ref text,
    activity_type text,
    milestone_id uuid,
    estimated_minutes integer,
    sort_order double precision,
    start_date date,
    assigned_to uuid NOT NULL,
    kanban_status text DEFAULT 'todo'::text NOT NULL,
    task_type text,
    locked boolean DEFAULT false NOT NULL,
    follow_up_of uuid,
    trigger_days integer,
    condition character varying(50),
    assignment_note text,
    reviewer_id uuid,
    review_note text,
    review_requested_at timestamp with time zone,
    completed_at timestamp with time zone,
    CONSTRAINT tasks_kanban_status_check CHECK ((kanban_status = ANY (ARRAY['inbox'::text, 'todo'::text, 'in_progress'::text, 'review'::text, 'done'::text]))),
    CONSTRAINT tasks_priority_check CHECK ((priority = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text]))),
    CONSTRAINT tasks_status_check CHECK ((status = ANY (ARRAY['open'::text, 'done'::text])))
);


--
-- Name: COLUMN tasks.assignment_note; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tasks.assignment_note IS 'Note written by the assigner when delegating. Shown on the task itself, not just in the notification.';


--
-- Name: COLUMN tasks.reviewer_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tasks.reviewer_id IS 'Who was asked to review. Set while a review is outstanding, cleared on approve or changes requested.';


--
-- Name: COLUMN tasks.review_note; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tasks.review_note IS 'What kind of review or help is wanted. Written by the requester.';


--
-- Name: COLUMN tasks.completed_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tasks.completed_at IS 'When the task was marked done. Cleared on reopen. Values predating migration 153 are backfilled from updated_at and are approximate.';


